      "arFull": "اَمِ اتَّخَذُوْا مِنْ دُوْنِهٖۤ اَوْلِیَآءَ ۚ فَاللّٰهُ هُوَ الْوَلِیُّ وَهُوَ یُحْیِ الْمَوْتٰی ؗ وَهُوَ عَلٰی كُلِّ شَیْءٍ قَدِیْرٌ ۟۠",
      "ur": "کیا ان لوگوں نے اللہ تعالیٰ کے سوا اور کارساز بنالیے ہیں، (حقیقتاً تو) اللہ تعالیٰ ہی کارساز ہے وہی مُردوں کو زنده کرے گا اور وہی ہر چیز پر قادر ہے.[1]",
      "en": "Or have they taken protectors [or allies] besides Him? But Allāh - He is the Protector, and He gives life to the dead, and He is over all things competent.",
      "footnotesUr": "[1] جب یہ بات ہے تو پھر اللہ تعالیٰ ہی اس بات کا مستحق ہے کہ اس کو ولی اور کارساﺯ مانا جائے نہ کہ ان کو جن کے پاس کوئی اختیاری ہی نہیں ہے، اور جو سننے اور جواب دینے کی طاقت رکھتے ہیں، نہ نفع ونقصان پہنچانے کی صلاحیت۔",
      "footnotesEn": null,
