      "arFull": "وَهُوَ الَّذِیْ یَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهٖ وَیَعْفُوْا عَنِ السَّیِّاٰتِ وَیَعْلَمُ مَا تَفْعَلُوْنَ ۟ۙ",
