      "arFull": "وَیَسْتَجِیْبُ الَّذِیْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ وَیَزِیْدُهُمْ مِّنْ فَضْلِهٖ ؕ وَالْكٰفِرُوْنَ لَهُمْ عَذَابٌ شَدِیْدٌ ۟",
