      "en": "And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.",
      "footnotesUr": "[1] یعنی ان کی دعائیں سنتا ہے اور ان کی خواہشیں اور آرزوئیں پوری فرماتا ہے۔ بشرطیکہ دعا کے آداب وشرائط کا بھی پورا اہتمام کیا گیا ہو۔ اور حدیث میں آتا ہے کہ اللہ بندے کی توبہ سے اس شخص سے بھی زیادہ خوش ہوتا ہے جس کی سواری مع کھانے پینے کے سامان کے، صحرا، بیابان میں گم ہوجائے اور وہ ناامید ہوکر کسی درخت کے نیچے لیٹ جائے کہ اچانک اسے اپنی سواری مل جائے اور فرط مسرت میں اس کے منہ سے نکل جائے، اے اللہ! تو میرا بندہ اور میں تیرا رب یعنی شدت فرح میں وہ غلطی کرجائے۔ (صحيح مسلم كتاب التوبة ، باب في الحض على التوبة والفرح بها)۔",
