      "arFull": "وَهُوَ الَّذِیْ یُنَزِّلُ الْغَیْثَ مِنْ بَعْدِ مَا قَنَطُوْا وَیَنْشُرُ رَحْمَتَهٗ ؕ وَهُوَ الْوَلِیُّ الْحَمِیْدُ ۟",
      "ur": "اور وہی ہے جو لوگوں کے ناامید ہوجانے کے بعد بارش برساتا[1] اور اپنی رحمت پھیلا دیتا ہے وہی ہے کارساز اور قابل حمد و ثنا.[2]",
      "en": "And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.",
      "footnotesUr": "[1] جو انواع رزق کی پیداوار میں سب سے زیادہ مفید اور اہم ہے۔ یہ بارش جب ناامیدی کے بعد ہوتی ہے تو اس نعمت کا صحیح احساس بھی اسی وقت ہوتا ہے۔ اللہ تعالیٰ کے اس طرح کرنے میں حکمت بھی یہی ہے کہ بندے اللہ کی نعمتوں کی قدر کریں اور اس کا شکر بجالائیں۔\n[2] کارساز ہے، اپنے نیک بندوں کی چارہ سازی فرماتا ہے، انہیں منافع سے نوازتا اور شرور ومہلکات سے ان کی حفاظت فرماتا ہے۔ اپنے ان انعامات بے پایاں اور احسانات فراواں پر قابل حمد وثنا ہے۔",
