      "en": "And of His signs are the ships in the sea, like mountains.",
      "footnotesUr": "[1] الْجَوَارِ یا الْجَوَارِي جَارِيَةٌ (چلنے والی) کی جمع ہے، بمعنی کشتیاں، جہاز، یہ اللہ کی قدرت تامہ کی دلیل ہے کہ سمندروں میں پہاڑوں جیسی کشتیاں اور جہاز اس کے حکم سے چلتے ہیں، ورنہ اگر وہ حکم دے تو یہ سمندروں میں ہی کھڑے رہیں۔",
