      "arFull": "وَالَّذِیْنَ یَجْتَنِبُوْنَ كَبٰٓىِٕرَ الْاِثْمِ وَالْفَوَاحِشَ وَاِذَا مَا غَضِبُوْا هُمْ یَغْفِرُوْنَ ۟ۚ",
