      "footnotesUr": "[1] یعنی لوگوں سے عفو ودرگزر کرنا ان کے مزاج وطبیعت کا حصہ ہے نہ کہ انتقام اور بدلہ لینا۔ جس طرح نبی (صلى الله عليه وسلم) کے بارے میں آتا ہے۔ ”مَا انْتَقَمَ لِنَفْسِهِ قَطُّ إِلا أَنْ تُنْتَهَكَ حُرُمَات اللهِ“ (البخاري ، كتاب الأدب ، باب يسروا ولا تعسروا - مسلم كتاب الفضائل، باب مباعدته صلى الله عليه وسلم للآثام) نبی (صلى الله عليه وسلم) نے اپنی ذات کے لیے کبھی بدلہ نہیں لیا، ہاں اللہ تعالیٰ کی حرمتوں کا توڑا جانا آپ کے لیے ناقابل برداشت تھا۔",
