      "arFull": "وَالَّذِیْنَ اِذَاۤ اَصَابَهُمُ الْبَغْیُ هُمْ یَنْتَصِرُوْنَ ۟",
      "ur": "اور جب ان پر ﻇلم (و زیادتی) ہو تو وه صرف بدلہ لے لیتے ہیں.[1]",
      "en": "And those who, when tyranny strikes them, they retaliate [in a just manner].[1425]",
      "footnotesUr": "[1] یعنی بدلہ لینے سے وہ عاجز نہیں ہیں، اگر بدلہ لینا چاہیں تو لے سکتے ہیں، تاہم قدرت کے باوجود وہ معافی کو ترجیح دیتے ہیں جیسے نبی (صلى الله عليه وسلم) نے فتح مکہ والے دن اپنے خون کے پیاسوں کے لیے عفوعام کا اعلان فرما دیا، حدیبیہ میں آپ نے ان 80 آدمیوں کو معاف کردیا، جنہوں نے آپ کے خلاف سازش تیار کی تھی، لبید بں عاصم یہودی سے بدلہ نہیں لیا جس نے آپ پر جادو کیا تھا، اس یہودیہ عورت کو آپ نے کچھ نہیں کہا جس نے آپ کے کھانے میں زہر ملادیا تھا، جس کی تکلیف آپ دم واپسیں تک محسوس فرماتے رہے، (صلى الله عليه وسلم) (ابن کثیر)۔",
      "footnotesEn": "[1425] Restoring their rights and not allowing aggressors to take advantage of them out of weakness.",
