      "arFull": "وَمَا كَانَ لَهُمْ مِّنْ اَوْلِیَآءَ یَنْصُرُوْنَهُمْ مِّنْ دُوْنِ اللّٰهِ ؕ وَمَنْ یُّضْلِلِ اللّٰهُ فَمَا لَهٗ مِنْ سَبِیْلٍ ۟ؕ",
